function parse(tokens) {
  let p = 0;
  const peek = () => tokens[p];
  const eat = (t) => {
    if (tokens[p].type !== t) throw new Error(`${t} 가 필요한데 ${tokens[p].type} 이 왔다 (위치 ${tokens[p].at})`);
    return tokens[p++];
  };

  // 낮은 우선순위가 바깥, 높은 것이 안쪽
  function expr() {                        // + -
    let left = term();
    while (peek().type === '+' || peek().type === '-') {
      const op = tokens[p++].type;
      left = { kind: 'bin', op, left, right: term() };
    }
    return left;
  }
  function term() {                        // * /
    let left = atom();
    while (peek().type === '*' || peek().type === '/') {
      const op = tokens[p++].type;
      left = { kind: 'bin', op, left, right: atom() };
    }
    return left;
  }
  function atom() {                        // 숫자 · 이름 · 괄호
    const t = peek();
    if (t.type === 'num') { p++; return { kind: 'num', value: t.value }; }
    if (t.type === 'name') { p++; return { kind: 'var', name: t.value }; }
    if (t.type === '(') { p++; const e = expr(); eat(')'); return e; }
    throw new Error(`값이 필요한데 ${t.type} 이 왔다 (위치 ${t.at})`);
  }

  const ast = expr();
  eat('eof');                              // 남은 게 있으면 오류
  return ast;
}
